"""Create the train revision audit report and freeze a future matched experiment."""
import json,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from findelta.common import read_jsonl,write_json,sha256,prompt_sha256
root=Path(__file__).resolve().parents[1]
review=root/'data/reviews/train-repair-v2';cohort=root/'data/cohort/v2-reviewed';out=root/'reports/train-repair-v2'
out.mkdir(parents=True,exist_ok=True)
m=json.loads((cohort/'manifest.json').read_text());v=json.loads((cohort/'validation.json').read_text());ds=read_jsonl(review/'decisions.jsonl');changes=read_jsonl(cohort/'changes.jsonl')
assert v['passed'] and m['counts']=={'parent_train':1000,'train':966,'matched_control':966,'reviewed':82,'unreviewed_retained':918,'repaired':11,'quarantined':34,'reviewed_kept':37,'dev':200,'test':200}
old=json.loads((root/'reports/week1-duration-v1/sft3-adapter/run_manifest.json').read_text())
infer=json.loads((root/'reports/week1-duration-v1/inference-config.json').read_text())
protocol={'status':'PLANNED_NOT_STARTED','purpose':'Isolate the effect of 11 reviewed target corrections on the same retained training examples','cohort_manifest_sha256':sha256(cohort/'manifest.json'),'control_sft_sha256':sha256(cohort/'sft-control.jsonl'),'repaired_sft_sha256':sha256(cohort/'sft.jsonl'),'dev_sha256':sha256(cohort/'dev.jsonl'),'prompt_sha256':prompt_sha256(),'training_config':old['config'],'inference_config':infer,'initialization':'Both start independently from the pinned base model; neither continues SFT or DPO adapters','arms':{'control':'966 retained examples with original targets','repaired':'The same 966 examples/order/prompts, with exactly 11 reviewed target changes'},'primary_endpoint':'Verified accuracy on the unchanged 200-question dev with the existing deterministic executor','secondary_endpoint':'Raw model verified accuracy on the same dev','training_seed':42,'epochs':3,'planned_runs':2,'test_evaluation':False,'prior_1000_row_baseline':'Descriptive only; comparisons to it mix quarantine/composition and label effects','limitations':['Single-seed exploratory dev analysis','Only 4 numerical answers change; 7 corrections change original source-row binding','Development labels retain known general noise risks','No DPO preference expansion or training in this revision step']}
if (out/'next-experiment.json').exists():assert json.loads((out/'next-experiment.json').read_text())==protocol
else:write_json(out/'next-experiment.json',protocol)
write_json(out/'validation.json',{'passed':True,'core_regression_tests':28,'new_revision_tests':6,'cohort_validation':v,'counts':m['counts'],'model_training_started':False,'original_v1_unchanged':True,'manifest_sha256':sha256(cohort/'manifest.json'),'next_experiment_sha256':sha256(out/'next-experiment.json')})
lines=['# FinDelta：训练数据修正版 v2-reviewed','', '**本轮已生成可训练的数据修正版及匹配对照，尚未重新训练或产生新模型分数。**','', '原 1,000 道训练题中，重新裁定先前审核的 80 个偏好候选及 2 个原始材料已确认的年份矛盾，共 82 题：11 题修复、37 题保留、34 题隔离。其余 918 题沿用原版，尚未逐题证明语义正确。最终训练数据 966 题。审核者是 AI 助手，人工审核数为 0。','', '## 本轮完成了什么','', '| 项目 | 数量 / 状态 |','|---|---|','| 修复原始证据行绑定 | 7 题，数值答案不变 |','| 修复时间方向 | 2 题 |','| 修复会计负号 | 1 题 |','| 修复金额误标为比例 | 1 题 |','| 已审核并保持原目标 | 37 题 |','| 保守隔离 | 34 题；包含错标、歧义和证据不足，不等于 34 个确定错误 |','| 尚未逐题审核、继续保留 | 918 题 |','| 修正版 / 同样本对照 | 各 966 题、相同顺序和 prompt |','| 开发集 / 测试集 | 各 200 题，文件逐字节与 v1 一致 |','| 核心与回归测试 | 28 项通过，含 6 项新增版本与绑定测试 |','', '## 为什么不能把拒绝的偏好全部删掉','', 'DPO 要求 chosen 明确优于 rejected；SFT 只要求目标本身合理。先前排除的 5 对包含可保留的 SFT 目标，例如收益率差 0.55 与 55 个百分点是尺度等价，不能把后者当强语义负例，但前者可沿用作小数形式的 SFT 目标。因此这 5 题保留，偏好仍不批准。','', '本次没有统一重写所有单位，也没有添加新的模型输出字段。对金额单位、百分数尺度或比较方向仍不清楚的样本，记录原因后隔离；不悄悄给问题补充未声明的条件。`answer_unit` 和原始单元格的指标/期间注解仅用于审计，不进入模型输入。','', '## 11 个修正','', '| ID | 类型 | 原答案 | 修正答案 |','|---|---|---:|---:|']
for c in changes:lines.append(f"| {c['id']} | {c['category']} | {c['before']['answer']:.10g} | {c['after']['answer']:.10g} |")
for c in changes:lines+=['',f"### {c['id']}",'',c['rationale']]
lines+=['','## 新增校验能证明什么','', '旧检查只确认数字出现在引用的文本里。表格序列化会把首行重复为其他行的标题，导致 cash=45826 可以错误绑定到 total 行且仍通过数值检查。新增校验对这 11 个修复目标使用手工指定的原始行、列、原始单元格及符号语义：引用行必须对应原始行，单元格文本必须匹配，并核对所有证据操作数。','', '另加入对 `-121 (121)` 等源数据形式的窄解析，默认保留会计负号；税额作为覆盖率分子时只有显式标注 magnitude 才允许取绝对值。这些规则已用重复标题误绑定、负号丢失、缺失注解、旧文件变动和混入 holdout ID 等失败用例验证。','', '**它仍不是自动金融语义验证器。** 指标、期间、单位和正确行列的注解由助手审核；程序校验这些显式注解的一致性，不能自动判断所有自然语言问题是否对应某个指标。它也未修改旧 dev/test 的评分规则，旧分数继续保留原有局限。','', '全部 966 个训练目标均通过原有 schema/执行器检查；两个 SFT 文件最大长度均为 1,528 tokens，低于 2,048 上限，没有截断。两组相同题目、顺序和输入，仅 11 个 completion 不同。构建器先校验再写入，拒绝覆盖已有数据版本；所有来源、审核和父版本有 SHA256。','', '## 下一次训练如何比较','', '协议已冻结于 `next-experiment.json`，状态为 PLANNED_NOT_STARTED：','', '1. control：保留的相同 966 题，仍用原始目标，从固定 base 模型训练 3 epochs。','2. repaired：相同 966 题、顺序、prompt、训练配置和 seed 42，仅替换 11 个目标，从相同 base 独立训练 3 epochs。','3. 两组在原始 200 题 dev 上，以同一解码设置、执行器和配对报告分组区间比较。主指标为执行器后 verified，次指标为原始 verified；test 不预测。','', '原来 1,000 题 SFT 的 44.5% 可作为历史参考，但与 966 题新模型比较同时混入删题、训练步数和标签变化，不能独自证明“修标签提高了分数”。匹配对照才用于隔离修标签的作用。因只有 4 个数值目标变化，另 7 个只改来源，当前仍没有理由承诺模型提升。','', '本轮未扩大 DPO 数据或把修正后模型输出重新标为偏好。下一轮 SFT 对照后再决定是否采样新偏好。','', '## 文件和复现','', '- 审核记录：`data/reviews/train-repair-v2/decisions.jsonl`，含裁定、原始行哈希、替代程序、独立算式结果和逐操作数单元格注解。','- 原始材料快照：同目录 `source-records.jsonl`，只包含本次本项目 train 的 82 个 ID；保留原始 FinQA 文件哈希。','- 修正版：`data/cohort/v2-reviewed/train.jsonl`、`sft.jsonl`；匹配对照：`train-control.jsonl`、`sft-control.jsonl`。','- 隔离原文与原因：`quarantine.jsonl`；前后差异：`changes.jsonl`；版本与检查：`manifest.json`、`validation.json`。','- 构建脚本：`scripts/build_reviewed_revision.py`。输出路径必须新建，避免覆盖冻结版本。','', '```bash','python scripts/build_reviewed_revision.py --out data/cohort/v2-rebuild','python -m unittest discover -s tests -v','```','', '新数据经验证适合进入有边界的对照试验；这不等于整批数据已无噪声、模型已改善或已完成严格事实性验证。','']
(out/'REPORT.zh.md').write_text('\n'.join(lines))
print(json.dumps({'report':str(out/'REPORT.zh.md'),'counts':m['counts'],'next_experiment_status':protocol['status']},ensure_ascii=False))
